import { Eye, EyeOff } from 'lucide-react'
import { useId, useState } from 'react'

import { cx } from '~/lib/cx'

import { Label } from './label'
import styles from './password-input.module.scss'

const STRENGTH = [
  { label: 'Too short', tone: 'destructive' },
  { label: 'Weak', tone: 'destructive' },
  { label: 'Fair', tone: 'warning' },
  { label: 'Good', tone: 'info' },
  { label: 'Strong', tone: 'success' },
] as const

type StrengthTone = (typeof STRENGTH)[number]['tone']

const TONE: Record<StrengthTone, string> = {
  destructive: styles.toneDestructive,
  warning: styles.toneWarning,
  info: styles.toneInfo,
  success: styles.toneSuccess,
}

function scorePassword(value: string): number {
  if (!value) return 0
  let score = 0
  if (value.length >= 8) score += 1
  if (value.length >= 12) score += 1
  if (/[a-z]/.test(value) && /[A-Z]/.test(value)) score += 1
  if (/\d/.test(value) && /[^A-Za-z0-9]/.test(value)) score += 1
  return Math.min(4, score)
}

export interface PasswordStrengthInputProps {
  value: string
  onChange: (value: string) => void
  label?: string
  hint?: string
  error?: string
  disabled?: boolean
  autoComplete?: string
  showStrength?: boolean
  className?: string
  id?: string
}

export function PasswordStrengthInput({
  value,
  onChange,
  label = 'Password',
  hint,
  error,
  disabled = false,
  autoComplete = 'current-password',
  showStrength = true,
  className,
  id,
}: PasswordStrengthInputProps) {
  const [visible, setVisible] = useState(false)
  const generatedId = useId()
  const inputId = id ?? generatedId
  const strengthId = `${inputId}-strength`
  const score = scorePassword(value)
  const strength = STRENGTH[score]

  return (
    <div className={cx(styles.root, className)}>
      <Label htmlFor={inputId}>{label}</Label>

      <div className={cx(styles.shell, error && styles.invalid)}>
        <input
          id={inputId}
          type={visible ? 'text' : 'password'}
          value={value}
          onChange={(event) => onChange(event.target.value)}
          disabled={disabled}
          autoComplete={autoComplete}
          aria-invalid={error ? true : undefined}
          aria-describedby={
            [
              error ? `${inputId}-error` : null,
              hint ? `${inputId}-hint` : null,
              showStrength ? strengthId : null,
            ]
              .filter(Boolean)
              .join(' ') || undefined
          }
          className={styles.input}
        />
        <button
          type="button"
          onClick={() => setVisible((v) => !v)}
          disabled={disabled}
          aria-label={visible ? 'Hide password' : 'Show password'}
          aria-pressed={visible}
          className={styles.toggle}
        >
          {visible ? (
            <EyeOff aria-hidden className={styles.toggleIcon} />
          ) : (
            <Eye aria-hidden className={styles.toggleIcon} />
          )}
        </button>
      </div>

      {showStrength && value ? (
        <div id={strengthId} aria-live="polite" className={styles.strength}>
          <div className={styles.bars} aria-hidden>
            {[0, 1, 2, 3].map((index) => (
              <span
                key={index}
                className={cx(
                  styles.bar,
                  index < Math.max(1, score) && TONE[strength.tone],
                )}
              />
            ))}
          </div>
          <p className={styles.strengthText}>
            Password strength:{' '}
            <span className={styles.strengthValue}>{strength.label}</span>
          </p>
        </div>
      ) : null}

      {hint && !error ? (
        <p id={`${inputId}-hint`} className={styles.hint}>
          {hint}
        </p>
      ) : null}
      {error ? (
        <p id={`${inputId}-error`} role="alert" className={styles.error}>
          {error}
        </p>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  gap: vz.space(1.5);
  min-width: 0;
}

.shell {
  display: flex;
  align-items: center;
  min-height: vz.space(10);
  overflow: hidden;
  border: 1px solid vz.color('input');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  color: vz.color('foreground');
  transition:
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out');

  &:focus-within {
    border-color: vz.color('ring');
    box-shadow: 0 0 0 2px vz.color('ring', 0.3);
  }
}

.invalid {
  border-color: vz.color('destructive');

  &:focus-within {
    border-color: vz.color('destructive');
    box-shadow: 0 0 0 2px vz.color('destructive', 0.2);
  }
}

.input {
  flex: 1;
  min-width: 0;
  height: 100%;
  padding-inline: vz.space(3);
  padding-block: vz.space(2);
  border: 0;
  background: transparent;
  color: inherit;
  font-family: inherit;
  font-size: vz.font-size('sm');
  caret-color: vz.color('primary');
  outline: none;

  @include vz.disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

.toggle {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: vz.space(9);
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition: color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    color: vz.color('foreground');
  }

  &:focus-visible {
    color: vz.color('foreground');
    outline: 2px solid vz.color('ring', 0.6);
    outline-offset: -2px;
  }

  @include vz.disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

.toggle-icon {
  @include vz.icon(4);
}

.strength {
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
}

.bars {
  display: flex;
  gap: vz.space(1);
}

.bar {
  flex: 1;
  height: vz.space(1);
  border-radius: vz.radius('full');
  background: vz.color('muted');
  transition: background-color vz.duration('base') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.tone-destructive {
  background: vz.color('destructive');
}

.tone-warning {
  background: vz.color('warning');
}

.tone-info {
  background: vz.color('info');
}

.tone-success {
  background: vz.color('success');
}

.strength-text {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}

.strength-value {
  color: vz.color('foreground');
  font-weight: 500;
}

.hint {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}

.error {
  margin: 0;
  color: vz.color('destructive');
  font-size: vz.font-size('xs');
}
